import React, {
  createContext,
  useContext,
  useEffect,
} from "react";

const GeneratedSpaceRuntimeContext = createContext(null);
const ACTION_ENDPOINT_RELATIVE_URL = "./actions";
const ACTION_STREAM_ENDPOINT_RELATIVE_URL = "./actions_stream";

let activeClientRuntime = null;

async function* parseNdjsonStream(body) {
  const reader = body.getReader();
  const decoder = new TextDecoder();
  let buffer = "";

  while (true) {
    const { done, value } = await reader.read();
    if (done) {
      buffer += decoder.decode();
      break;
    }
    buffer += decoder.decode(value, { stream: true });
    while (true) {
      const newlineIndex = buffer.indexOf("\n");
      if (newlineIndex < 0) {
        break;
      }
      const line = buffer.slice(0, newlineIndex).trim();
      buffer = buffer.slice(newlineIndex + 1);
      if (line.length === 0) {
        continue;
      }
      yield JSON.parse(line);
    }
  }

  const trailingLine = buffer.trim();
  if (trailingLine.length > 0) {
    yield JSON.parse(trailingLine);
  }
}

function buildActionPayload(name, args) {
  return {
    action: name,
    args,
  };
}

function resolveActionEndpoint(relativeEndpoint) {
  const href = globalThis.location?.href;
  if (typeof href !== "string" || href.trim().length === 0) {
    return relativeEndpoint;
  }

  const baseUrl = new URL(href);
  baseUrl.hash = "";
  baseUrl.search = "";
  if (!baseUrl.pathname.endsWith("/")) {
    baseUrl.pathname = `${baseUrl.pathname}/`;
  }
  return new URL(relativeEndpoint.replace(/^\.\//, ""), baseUrl).toString();
}

async function postAction(relativeEndpoint, name, args) {
  const response = await fetch(resolveActionEndpoint(relativeEndpoint), {
    body: JSON.stringify(buildActionPayload(name, args)),
    credentials: "include",
    headers: {
      "content-type": "application/json",
    },
    method: "POST",
  });
  if (!response.ok) {
    throw new Error((await response.text()) || `Action ${name} failed`);
  }
  const payload = await response.json();
  if (typeof payload.error === "string" && payload.error.length > 0) {
    throw new Error(payload.error);
  }
  if (!Object.hasOwn(payload, "data")) {
    throw new Error(`Action ${name} completed without a result`);
  }
  return payload.data;
}

export function createClientRuntime(bootstrap) {
  const runtime = {
    bootstrap,
    destroy() {
      if (activeClientRuntime === runtime) {
        activeClientRuntime = null;
      }
    },
    async executeAction(name, args) {
      return postAction(ACTION_ENDPOINT_RELATIVE_URL, name, args);
    },
    async *executeActionStream(name, args) {
      const response = await fetch(resolveActionEndpoint(ACTION_STREAM_ENDPOINT_RELATIVE_URL), {
        body: JSON.stringify(buildActionPayload(name, args)),
        credentials: "include",
        headers: {
          "content-type": "application/json",
        },
        method: "POST",
      });
      if (!response.ok || response.body == null) {
        throw new Error((await response.text()) || `Action ${name} failed`);
      }
      for await (const message of parseNdjsonStream(response.body)) {
        if ("error" in message) {
          throw new Error(message.error);
        }
        yield message.data;
      }
    },
  };
  activeClientRuntime = runtime;
  return runtime;
}

export function GeneratedSpaceRuntimeProvider({ children, runtime }) {
  useEffect(() => {
    activeClientRuntime = runtime;
    return () => {
      if (activeClientRuntime === runtime) {
        activeClientRuntime = null;
      }
    };
  }, [runtime]);

  return React.createElement(
    GeneratedSpaceRuntimeContext.Provider,
    { value: runtime },
    children
  );
}

function useGeneratedSpaceRuntime() {
  const runtime = useContext(GeneratedSpaceRuntimeContext);
  if (runtime == null) {
    throw new Error("Generated space runtime is not initialized");
  }
  return runtime;
}

function assertClientRuntime() {
  if (activeClientRuntime == null) {
    throw new Error("Generated space client runtime is not initialized");
  }
  return activeClientRuntime;
}

export async function executeAction(name, args) {
  return assertClientRuntime().executeAction(name, args);
}

export function executeActionStream(name, args) {
  return assertClientRuntime().executeActionStream(name, args);
}

export function useGeneratedSpaceBootstrap() {
  const runtime = useGeneratedSpaceRuntime();
  return runtime.bootstrap;
}
